create function public.trackers_common_snapshot(p_week_start date) returns jsonb language sql stable security invoker set search_path='' as $$
with params as(select public.monday_bucket(p_week_start) week_start,(now() at time zone 'Asia/Kolkata')::date today),
people as(select id,lower(btrim(email)) email,full_name,team from public.profiles where is_active and not is_sample),
work as(select t.* from public.tasks t join people p on p.id=t.assigned_to_id where not t.archived and not t.is_sample),
workload as(select assigned_to_id,count(*) filter(where status not in ('COMPLETED','CANCELLED')) open_count,count(*) filter(where status not in ('COMPLETED','CANCELLED') and (current_due_date<(select today from params) or status in ('DUE_DATE_CROSSED','DUE_DATE_NOT_APPLIED'))) overdue_count,count(*) filter(where status='PENDING_APPROVAL') pending_approval_count from work group by assigned_to_id),
scored as(select se.* from public.task_score_events se join work t on t.id=se.task_id join people p on p.id=se.user_id where se.week_start=(select week_start from params)),
scores as(select user_id,count(*) filter(where color='GREEN') green,count(*) filter(where color='YELLOW') yellow,count(*) filter(where color='RED') red,count(*) measured,coalesce(sum(points),0) points from scored group by user_id),
rows as(select p.email,p.full_name name,coalesce(p.team,'') team,coalesce(w.open_count,0) open,coalesce(w.overdue_count,0) overdue,coalesce(w.pending_approval_count,0) pending_approval,coalesce(s.green,0) green,coalesce(s.yellow,0) yellow,coalesce(s.red,0) red,coalesce(s.measured,0) measured,coalesce(s.points,0) points,coalesce(s.measured,0)*3 max_points from people p left join workload w on w.assigned_to_id=p.id left join scores s on s.user_id=p.id)
select jsonb_build_object('source','taskops','generated_at',now(),'week_start',(select week_start from params),'week_end',(select week_start+6 from params),'revision',(select revision from trackers_private.change_signal where id),'people',coalesce((select jsonb_agg(to_jsonb(r) order by name) from rows r),'[]'::jsonb),'summary',jsonb_build_object('open',(select count(*) from work where status not in ('COMPLETED','CANCELLED')),'overdue',(select coalesce(sum(overdue),0) from rows),'green',(select count(*) from scored where color='GREEN'),'yellow',(select count(*) from scored where color='YELLOW'),'red',(select count(*) from scored where color='RED'),'measured',(select count(*) from scored)),'rules','TaskOps score events in the selected Monday–Sunday week. Events can include completion, due-date misses and week shifts; a task can have multiple events. Live workload excludes archived/sample/cancelled/completed tasks.');
$$;
revoke all on function public.trackers_common_snapshot(date) from public,anon,authenticated;
grant execute on function public.trackers_common_snapshot(date) to service_role;
create trigger trackers_tasks_changed after insert or update or delete on public.tasks for each statement execute function trackers_private.signal_change();
create trigger trackers_scores_changed after insert or update or delete on public.task_score_events for each statement execute function trackers_private.signal_change();
create trigger trackers_profiles_changed after insert or update or delete on public.profiles for each statement execute function trackers_private.signal_change();
create trigger trackers_targets_changed after insert or update or delete on public.weekly_targets for each statement execute function trackers_private.signal_change();
